window.SAQ_PAPER_QUESTIONS["2016-2-pah"]=[{"number":1,"title":"","stemText":"A 40 year old woman has presented to the ED with a severe headache.\nYou are considering the diagnosis of sub-arachnoid haemorrhage. She has a Glasgow coma score of 15 on your initial assessment.","parts":[{"id":"a","label":"Part A","prompt":"List 4 risk factors for subarachnoid haemorrhage.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ CT scan of the brain has confirmed the diagnosis."},{"id":"b","label":"Part B","prompt":"List the classification of severity for subarachnoid haemorrhage as per the World Federation of Neurosurgical Societies. (5 marks)\nAfter 3 hours in the ED, the patient was noted to have suffered a decline in her level of\nconsciousness."},{"id":"c","label":"Part C","prompt":"List 5 likely potential causes of this problem.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ On re-evaluation, her vital signs are:\n\nGCS\nE1 V2 M4 Pulse /min\n\nBP\n220/120 mmHg O2 saturation 99% room air"},{"id":"d","label":"Part D","prompt":"List 5 clinical priorities in the assessment and management of this situation. State your\njustification for each priority. (10 marks) Clinical priority Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Smoking</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Alcohol abuse</div><div class=\"answer-line\">Family Hx</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">WFNS</div><div class=\"answer-line\">1 – GCS 15</div><div class=\"answer-line\">2 – GCS 13-14 no focal deficitis</div><div class=\"answer-line\">3 – GCS 13-14 + focal deficits</div><div class=\"answer-line\">4 – GCS 7-12</div><div class=\"answer-line\">5 – GCS 3-6</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">SAH related</td></tr><tr><td>-</td><td>Hydrocephalus</td></tr><tr><td>-</td><td>Re-bleed</td></tr><tr><td>-</td><td>Seizure</td></tr><tr><td>-</td><td>(vasospasm not likely this early)</td></tr><tr><td colspan=\"2\">Non-SAH related</td></tr><tr><td>-</td><td>Opiate toxicity</td></tr><tr><td>-</td><td>CO2 narcosis from opiates</td></tr><tr><td>-</td><td>Hypoxia from pulmonary oedema</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Intubate – protect airway, control O2 and CO2</td><td>CT scan – exclude hydrocephalus and rebleed</td></tr><tr><td>Discuss with Neurosurgeons – facilitate definitive management, or EVD if needed</td><td>BP management – limit rebleed / complications while maintaining adequate CPP, aim systolic 160-</td></tr><tr><td>200 probably acceptable</td><td>nimodipine infusion – prevent vasospasm</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"Your registrar had placed a 67 year old woman on bi-level non-invasive ventilation (NIV) after assessing her to be experiencing an infective exacerbation of chronic obstructive airways disease. The patient has failed to improve. An arterial blood gas after 15 minutes of NIV has been performed:\n\nFiO2\n0.9\n\npH\n6.88 (7.35 - 7.45)\n\npCO2\n149 mmHg (35 - 45)\n\npO2\n335 mmHg (80 - 100)\n\nHCO3\nmmol/L (18 - 26)\n\nNa\n140 mmol/L (135 - 145)\n\nK\n3.5 mmol/L (3.2 - 4.5)\n\nCl\nmmol/L (100 - 110)","parts":[{"id":"a","label":"Part A","prompt":"List 2 pathological processes related to the patient’s acid-base status. For each, provide an explanation. Pathological process Explanation"},{"id":"b","label":"Part B","prompt":"List the other important pathological process. Include the formula you have used. (2 marks) Pathological process Formula The patient’s vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n95/55 mmHg O2 saturations 100%\n\nRR\n/min Temperature 38.5 degrees You agree with the registrar’s diagnosis and feel that aggressive intervention is appropriate for the patient."},{"id":"c","label":"Part C","prompt":"List 5 steps in the further management of this patient in the ED.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pathological process</td><td>Explanation</td></tr><tr><td>Severe Acute respiratory acidosis</td><td>raised pCO2 with very low pH 6.88</td></tr><tr><td>Chronic resp acidosis with metabolic</td><td>HCO3 is raised at 44 more than would be expected for a</td></tr><tr><td>compensation</td><td>purely acute process (expect about HCO3 of 34) ie raise of 1</td></tr><tr><td>mmol/L for every raise in 10mmHg of CO2</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pathological process</div><div class=\"answer-line\">Formula</div><div class=\"answer-line\">Raised A-a gradient / relative hypoxia</div><div class=\"answer-line\">A-a gradient = PAO2 – PaO2</div><div class=\"answer-line\">PACO2 = FiO2 (760 – PH2O) – PaCO2/0.8</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- intubate</div><div class=\"answer-line\">- hyperventilate to decrease CO2</div><div class=\"answer-line\">- reduce FiO2</div><div class=\"answer-line\">- IV Abs – ceftriaxone 1g / azithromycin 500mg (accept ben/pen and azithro)</div><div class=\"answer-line\">- IV fluids – 500-1000mL bolus repeat if needed aiming for systolic BP &gt;100mmHg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 25 year old fireman has been brought to ED after being pulled unconscious from an apartment fire. He has significant thermal burns. On arrival his vital signs are:\n\nGCS\nE3 V4 M5\n\nHR\n105 /min\n\nBP\n120/60 mmHg\n\nRR\n/min O2 saturation 95% 15L O2 via non-rebreather mask","parts":[{"id":"a","label":"Part A","prompt":"List 5 findings on examination that would indicate an airway threatening burn.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 relevant differential diagnoses for his altered level of consciousness\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ He has been successfully intubated. On assessment you note that he has deep burns to the entirety of both upper limbs and his anterior trunk."},{"id":"c","label":"Part C","prompt":"Calculate the % of body surface area involved in his burn injury. (1 mark)"},{"id":"d","label":"Part D","prompt":"Calculate this patient’s fluid requirements using Parkland formula. Body weight is 100kg. (3 marks) FORMULA RESULT ADMINISTRATION PRINCIPLE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Stridor</div><div class=\"answer-line\">Loss of voice/Hoarse voice/Odynophagia</div><div class=\"answer-line\">Marked Lip swelling</div><div class=\"answer-line\">Obvious oral cavity/oropharyngeal swelling</div><div class=\"answer-line\">Burnt nasal hair</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypoxia from burns</div><div class=\"answer-line\">Toxic from combustion – CO or cyanide</div><div class=\"answer-line\">Trauma from associated injury</div><div class=\"answer-line\">Heat Stroke</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">36%</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Parkland formula – 4ml/kg * %BSA</div><div class=\"answer-line\">4 * 36 * 100 = 14400 mL</div><div class=\"answer-line\">Half over first 8hrs, half over next 16hrs</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 25 year old woman has been brought to the ED with neck pain after falling off a trampoline.","parts":[{"id":"a","label":"Part A","prompt":"List the NEXUS low-risk criteria for the clinical exclusion of cervical spine fracture. (5 marks) Her cervical spine x-ray is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 4 important radiological abnormalities on this x-ray.\n(1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"What is the clinical relevance of this injury? (1 mark) On examination, the patient has some upper limb weakness."},{"id":"d","label":"Part D","prompt":"Complete the table, listing the nerve root supply for the following upper limb actions. (4 marks)"}],"propPages":["asset:img7521851c70d3e37ff5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">No midline tenderness</div><div class=\"answer-line\">No neurological abnormalities</div><div class=\"answer-line\">No distracting injury</div><div class=\"answer-line\">Not intoxicated</div><div class=\"answer-line\">No altered consciousness</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Soft tissue swelling in front of C6/7</div><div class=\"answer-line\">Antero-superior corner fracture C7</div><div class=\"answer-line\">Disruption of posterior spinal line</div><div class=\"answer-line\">Widening between spinous processes C6 – C7</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Unstable fracture cervical spine with posterior ligamentous disruption</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Upper limb action</td><td>Nerve root supply</td></tr><tr><td>Elbow flexion</td><td>C5/6</td></tr><tr><td>Elbow extension</td><td>C7/8</td></tr><tr><td>Wrist extension</td><td>C6/7</td></tr><tr><td colspan=\"2\">T1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"You have been asked to develop a regional protocol for clot retrieval in ischaemic stroke. You are working in the major referral centre of a health district with 3 other urban hospitals.","parts":[{"id":"a","label":"Part A","prompt":"List 4 important stakeholders you would involve from outside your Emergency Department.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 2 information sources you would review to establish the current standard of care for\npatients with ischaemic stroke. (2 marks) (1)_______________________________________________________________________________ (2)_______________________________________________________________________________ You undertake to write a draft protocol."},{"id":"c","label":"Part C","prompt":"List 5 accepted inclusion criteria for the use of intra-arterial clot retrieval you might list on your protocol. (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Other ED directors</div><div class=\"answer-line\">Ambulance Directors</div><div class=\"answer-line\">Neurology</div><div class=\"answer-line\">Radiology and Interventional Radiology</div><div class=\"answer-line\">Intensive Care</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Current ACEM Guideline/Policy Statement</div><div class=\"answer-line\">Regional practice</div><div class=\"answer-line\">Other college statements (ie RACP - neurologists)</div><div class=\"answer-line\">Recent peer-reviewed RCTs/ similar journal articles for clot retrieval</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Clinical stroke syndrome with NIHSS &gt;2</div><div class=\"answer-line\">Time point (accept anything up to 8 hours)</div><div class=\"answer-line\">Patient Consent</div><div class=\"answer-line\">Major vessel occlusion on CT (A) – up to first division of major named cerebral arteries</div><div class=\"answer-line\">Age &gt;18</div><div class=\"answer-line\">No contraindications – pretty much any of the standard things here.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 32 year old lady has presented with a fever and malaise for 12 hours. She is currently undergoing chemotherapy for breast cancer.","parts":[{"id":"a","label":"Part A","prompt":"List 5 important features you would seek in your history.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 important features of your examination.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ Her full blood examination reveals severe neutropaenia."},{"id":"c","label":"Part C","prompt":"List and justify 5 important factors that will impact your antimicrobial prescribing for this patient. (5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Degree of illness – ie severity of symptoms, complications (fluid loss)</div><div class=\"answer-line\">Last chemotherapy – helps to predict complications (ie neutropaenia)</div><div class=\"answer-line\">Underlying disease and therapeutic intent</div><div class=\"answer-line\">Presence of in-dwelling lines/devices</div><div class=\"answer-line\">Co-morbidities – particularly cardiac (chemo), immunomodifiers (DM)</div><div class=\"answer-line\">Others likely reasonable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Focal findings – to guide therapy</div><div class=\"answer-line\">Complications of lines – ie infected ports</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Past micro results/resistance – initial cover should be extended to cover these</div><div class=\"answer-line\">Presence of in-dwelling catheters/lines – ensure include staph cover + MRSA</div><div class=\"answer-line\">Local Protocols/biogram – ie resistant organisms (VRE/ESBL)</div><div class=\"answer-line\">Comorbidities ie renal failure – may require dose modification +/- alternate agent</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"Your director has asked you to establish a morbidity and mortality committee for your department.","parts":[{"id":"a","label":"Part A","prompt":"List 5 key steps you will undertake in establishing a committee.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ You have established a committee. One of your first tasks is to ensure that you are capturing all morbidity and mortality that may be a result of patient encounters in your emergency department."},{"id":"b","label":"Part B","prompt":"List 7 different measures you may use to identify morbidity and mortality associated with\nemergency department presentations. (7 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ (6)________________________________________________________________________________ (7)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Invite interest from stakeholders</div><div class=\"answer-line\">Gather information about requirements for M+M meetings eg medico-legal / college statements /</div><div class=\"answer-line\">other hospitals</div><div class=\"answer-line\">Establish committee</div><div class=\"answer-line\">Terms of reference</div><div class=\"answer-line\">Reporting lines</div><div class=\"answer-line\">Frequency of meetings</div><div class=\"answer-line\">Roles</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Representations with 24/48hr</div><div class=\"answer-line\">Deaths within 48hrs of discharge</div><div class=\"answer-line\">Deaths within 24hrs of admission</div><div class=\"answer-line\">Unplanned admissions to ICU from ward within 24h of admission</div><div class=\"answer-line\">Complaints (pts/GPs/ Inpatient teams)</div><div class=\"answer-line\">Missed pathology/radiology</div><div class=\"answer-line\">Meetings with inpatient teams eg ICU</div><div class=\"answer-line\">Audits of KPIs eg time to cath lab for STEMIs</div><div class=\"answer-line\">Others probably ok</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 3 year old boy has presented to the ED with a wheeze.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your clinical assessment (history and examination) that would support\nthe diagnosis of foreign body aspiration. (4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Complete the table with 2 other differential diagnoses for wheeze in this child. For each, give cardinal clinical assessment features that would support the diagnosis. (4 marks) Differential diagnosis Clinical assessment features"},{"id":"c","label":"Part C","prompt":"List 3 complications of foreign body aspiration.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Focal wheeze, monophonic</div><div class=\"answer-line\">Focal crackles</div><div class=\"answer-line\">Unilateral hyperinflation</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Differential diagnosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>asthma</td><td>Prolonged expiratory phase</td></tr><tr><td>Generalised polyphonic wheeze</td><td></td></tr><tr><td>Hx asthma</td><td></td></tr><tr><td>Viral pneumonitis</td><td>Viral prodrome – cough, rhinorrhea</td></tr><tr><td>fevers</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">Abscess</div><div class=\"answer-line\">Distal collapse</div><div class=\"answer-line\">bronchiectasis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are awaiting the arrival of a 35 year old female who has just delivered a term baby in an ambulance. You do not have specific information regarding the status of the baby or mother.","parts":[{"id":"a","label":"Part A","prompt":"List 3 key components of your preparation.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ On arrival, the mother has ongoing vaginal bleeding. The umbilical cord has been clamped and cut but the placenta has not been delivered. No medications have been given. Estimated blood\nloss is 500ml.\nThe mother’s vital signs are:\n\nGCS\nPulse /min\n\nBP\n120/75 mmHg O2 saturation 99% room air"},{"id":"b","label":"Part B","prompt":"List 5 management steps to address this situation.\n(1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ Other members of your team are assessing the baby. The child has been dried and stimulated."},{"id":"c","label":"Part C","prompt":"Complete the following table for the appropriate actions in response to different newborn heart rates. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Newborn Heart Rate</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">&lt;60/min</div><div class=\"answer-line\">Start Compressions (3) to ventilations (1)</div><div class=\"answer-line\">60-100/min</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">(tone, response)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 32 year old man has been brought to the ED after a high speed motor vehicle accident.\nHe was intubated in the field due to severe respiratory distress. There is no evidence of head injury. His initial chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 pathological processes seen on this x-ray. For each, provide the radiological\nevidence. (6 marks) Pathological process Radiological evidence The patient looks pale and sweaty.\nHis vital signs are:\nPulse 140 /min\n\nBP\n65/45 mmHg O2 sats 92%\n\nFiO2 1.0\nThe pelvic x-ray is normal. There are no long bone injuries. FAST scan imaging from the right upper quadrant is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"Give your interpretation of this image. (2 marks)"},{"id":"c","label":"Part C","prompt":"State your fluid resuscitation principles, including end-points. (3 marks)"},{"id":"d","label":"Part D","prompt":"List your 4 main management steps, apart from fluid resuscitation.\n(1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"}],"propPages":["asset:img7e6aec0821028073bb","asset:img750f733f4b84d4229b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pathological process</td><td>Radiological evidence</td></tr><tr><td>Right large haemothorax</td><td>Veiled opacification of right hemithorax</td></tr><tr><td>Substantial rim of blood around outside of lung</td><td></td></tr><tr><td>edge</td><td></td></tr><tr><td>Left hemi-diaphragm rupture</td><td>Stomach clearly evident superiorly displaced in</td></tr><tr><td>thorax</td><td></td></tr><tr><td>Loss of diaphragmatic outline</td><td></td></tr><tr><td>Left lung contusion (also accept haemothorax)</td><td>Opacification of visible left lung in upper zone</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Moderate/large  amount of fluid in Morrison’s pouch – intraperitoneal blood</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- Start with O negative blood</div><div class=\"answer-line\">- activate MTP aiming for 1:1:1 packed rbc:FFP:platelets</div><div class=\"answer-line\">- target systolic 80mmHg, cerebral perfusion defined by mentation, radial pulse palpable</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Right ICC to drain blood</div><div class=\"answer-line\">Left ICC to drain blood, decompress left hemithorax</div><div class=\"answer-line\">Insertion NGT to decompress stomach</div><div class=\"answer-line\">Urgently to OT for control of intra-abdominal bleeding and correction of diaphragm rupture</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 45 year old man has self-presented to your tertiary ED with 2 hours of central chest pain. His ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the primary underlying pathology with 3 supportive ECG findings. (4 marks) Primary pathology: Supportive findings: (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"State the most important complication shown on the ECG with 4 supportive ECG findings. (5 marks) Complication: Supportive findings: (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ The patient’s vital signs are:\n\nGCS\n\nBP\n105/70 mmHg O2 saturation 100% 6L O2 via Hudson mask Temperature 36.5 degrees"},{"id":"c","label":"Part C","prompt":"List 5 treatments you would employ for the primary underlying pathology.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 2 pharmacological options for managing the complication demonstrated on the ECG.\nInclude doses. (2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________"}],"propPages":["asset:imgb024ee7e8b26727ec5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Main Pathology:</div><div class=\"answer-line\">Inferolateral STEMI</div><div class=\"answer-line\">Supportive Findings:</div><div class=\"answer-line\">STE in inferior leads (II, III, aVF with STE III&gt;II suggestive of proximal RCA)</div><div class=\"answer-line\">STE in lateral leads V4-6</div><div class=\"answer-line\">Q wave in III</div><div class=\"answer-line\">ST depression in I and aVL (reciprocal change)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Main Complication:</div><div class=\"answer-line\">Monomorphic VT</div><div class=\"answer-line\">Supportive Features:</div><div class=\"answer-line\">Wide complex tachycardia, regular, rate 200/min</div><div class=\"answer-line\">Fusion beat</div><div class=\"answer-line\">QRS concordance</div><div class=\"answer-line\">AV dissociation</div><div class=\"answer-line\">Will accept capture beat (2nd last one)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia: titrated opiates (cautious GTN probably ok)</div><div class=\"answer-line\">Aspirin 300mg</div><div class=\"answer-line\">Other antiplatelet drug (clopidogrel or ticagrelor)</div><div class=\"answer-line\">Heparin (any type, appropriate dose)</div><div class=\"answer-line\">Cardiology referral for PCI</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Amiodarone 5mg/kg</div><div class=\"answer-line\">Lignocaine 1-2mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 64 year old man has been referred to ED with dyspnoea.\nHis CXR is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 important abnormalities on the above x-ray.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 differential diagnoses for his radiologic abnormalities.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 4 investigations you may order to clarify the cause of this man’s illness. For each\nresponse provide justification regarding the utility of the investigation. (8 marks) INVESTIGATION JUSTIFICATION"}],"propPages":["asset:img2212cd4baba8c76ad3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">RUL opacification</div><div class=\"answer-line\">Cavitating lesion with air-fluid level</div><div class=\"answer-line\">RUL collapse - Tracheal deviation and R hemithorax volume loss with elevation of horizontal fissure</div><div class=\"answer-line\">Opacification of superomedial segments of RML consistent with mass or consolidation</div><div class=\"answer-line\">Small left basal effusion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Neoplastic: Primary Lung (Bronch. Carcinoma, SCLC, NSCLC, carcinoid), Secondary mets</div><div class=\"answer-line\">Lung abscess - Bacterial Infection: Klebsiella, Pneumococcus, Staph.</div><div class=\"answer-line\">TB, other granulomatous diseases</div><div class=\"answer-line\">Vasculitis eg Wegener’s</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Sputum Culture: high yield for bacterial causes</td><td>TB stains, smears on sputum and cultures: positive smear indicates infectivity, culture excludes</td></tr><tr><td>disease (takes 4-6 weeks)</td><td>Sputum microscopy for malignant cells</td></tr><tr><td>CT Chest: can support specific diagnoses based on appearance, indicate complications (ie</td><td>metastases), and can indicate suitability for invasive tests (ie transbronchial biopsy)</td></tr><tr><td>Blood Culture: can provide sensitivity data for directing antimicrobial therapy in bacterial causes</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 45 year old man has been brought to the ED with abdominal pain for 6 hours.\nHis abdominal x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"What is the pathology demonstrated? (1 mark)"},{"id":"b","label":"Part B","prompt":"List 3 radiological features of the x-ray which support your diagnosis.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List the 2 most common causes of this pathology. List one examination finding that would\nsupport each cause. Cause Examination finding"},{"id":"d","label":"Part D","prompt":"List 3 metabolic complications you might expect in this patient. Provide a likely cause for each complication. (6 marks) Metabolic complication Cause"}],"propPages":["asset:img263a0b659bd1d055bb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Small bowel obstruction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dilated loops of bowel</div><div class=\"answer-line\">Many air/fluid levels</div><div class=\"answer-line\">Small bowel – plicae circulares, central location, no large bowel gas</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Adhesions – abdominal wall scars from previous surgeries</div><div class=\"answer-line\">Inguinal herniae – presence of inguinal hernia on examination</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Metabolic complication</td><td>Cause</td></tr><tr><td>Metabolic alkalosis</td><td>Loss of HCl through vomiting</td></tr><tr><td>3rd spacing in to gut</td><td></td></tr><tr><td>hyponatremia</td><td></td></tr><tr><td>From hypoperfusion due to dehydration through 3rd space</td><td></td></tr><tr><td>Lactic acidosis</td><td></td></tr><tr><td>losses in to gut</td><td></td></tr><tr><td>Probably many others here acceptable</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 9 year old boy has been brought to the ED with bleeding from his mouth. He underwent\ntonsillectomy at your hospital 6 days ago.","parts":[{"id":"a","label":"Part A","prompt":"In order of increasing invasiveness, state four methods you could employ to reduce the amount of bleeding from the surgical site. (4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ After a short time in the ED, his bleeding has increased in volume. The patient has become agitated and is having trouble managing his airway, with continuous coughing and choking episodes. You have decided to intubate the patient to facilitate further safe management."},{"id":"b","label":"Part B","prompt":"List 4 issues you would anticipate during the period around his intubation. For each, state how you will aim to manage the problem. (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ice gargles</div><div class=\"answer-line\">Hydrogen peroxide gargles</div><div class=\"answer-line\">Co-phenylcaine spray</div><div class=\"answer-line\">Adrenaline soaked gauze on Magill’s forceps</div><div class=\"answer-line\">Intubation and packing</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Issue</th><th>Management</th></tr></thead><tbody><tr><td>\u0001 Hypoxia post induction / difficulty pre-oxygenation / aspiration lung injury</td><td>\u0002 15LO2 via NRB plus nasal prongs at max, sit up until stops breathing, 2 suckers, apnoeic</td></tr><tr><td>intubation as fast as possible (use of NIV would be incorrect given blood)</td><td>\u0001 hypotension post induction</td></tr><tr><td>\u0002 2 IV access, adequate fluid load 20mL/kg N/S pre-induction, have O negative blood ready for</td><td>use</td></tr><tr><td>\u0001 difficult laryngoscopy due to blood</td><td>\u0002 use 2 suckers, extra assistant, have backup airway equipment ready esp LMA</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 64 year old man has presented to the ED after a transient loss of consciousness while at home. On arrival to the ED, he has returned to normal consciousness and has normal vital signs. He has no symptoms.","parts":[{"id":"a","label":"Part A","prompt":"List 6 ECG findings that would warrant admission to a cardiac telemetry bed in the\nhospital. For each ECG finding, state the clinical significance. (12 marks) ECG finding Clinical significance"},{"id":"b","label":"Part B","prompt":"For each the following investigations, give a clinical indication for its use. Investigation Clinical indication Chest x-ray Full blood count Electrolyte panel CT head"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Long QT – risk of Torsades de Pointes</td><td>Q waves – evidence of previous MI with structural disease, risk of VT</td></tr><tr><td>“tri-fascicular block” / bifascicular block with 1st degree HB – risk of complete HB</td><td>Pre-excitation / delta waves – WPW syndrome</td></tr><tr><td>RBBB with ST elevation V1-3 – Brugada syndrome, risk VT/VF</td><td>Negative T waves V1-2, epsilon waves – ARVD – risk VT/VF</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CXR – SOB with focal examination findings eg crackles</td><td>FBC – any clinical finding suggests anaemia, but will not accept “baseline” or look for anaemia</td></tr><tr><td>Electrolytes – lots of possible answers but must be JUSTIFICATION</td><td>CT head – focal neurological abnormalities / head trauma from fall / headache / anti-coagulation</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 65 year old lady has been brought to ED after taking an overdose of iron tablets in a suicide attempt.","parts":[{"id":"a","label":"Part A","prompt":"List 5 key components of your toxicological risk assessment of the overdose.\n(5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Complete the table for assessment features (2 each for history, examination and investigations) that would be most predictive of a potentially lethal iron ingestion. (6 marks)"},{"id":"c","label":"Part C","prompt":"List 2 methods of decontamination that might be useful in this patient.\n(2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"Name the specific therapy for severe iron toxicity. (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dose – ingested dose, single ingestion vs staggered</div><div class=\"answer-line\">Time of Ingestion – determine time of peak toxicity</div><div class=\"answer-line\">Clinical Course - ?any GI symptoms yet to suggest significant toxicity</div><div class=\"answer-line\">Patient Factors – PMHx – determine cardiorespiratory reserve</div><div class=\"answer-line\">Co-ingestion - ?other expected toxidromes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Examination: Shock (accept hypotension),  Altered Mental State</div><div class=\"answer-line\">Investigations: Serum iron levels high (&gt;90) , HAGMA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Endoscopy</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">4. Desferrioxamine</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 45 year old man has presented to the ED with right shoulder pain after falling on to his right arm while playing basketball. His right shoulder x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 radiological abnormalities to describe the above injury.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ You plan to manage this injury in the ED prior to outpatient specialist referral.\nThe patient weighs 80kg and has no other medical problems."},{"id":"b","label":"Part B","prompt":"List 3 techniques for correction of this problem in the ED.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 4 different regimes for sedation and analgesia to facilitate your management.\n(1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"}],"propPages":["asset:img62c5560c9265bd9399"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Anterior dislocation of right humeral head</div><div class=\"answer-line\">Inferior dislocation of right humeral head</div><div class=\"answer-line\">Hill-Sach’s fracture</div><div class=\"answer-line\">Greater tubercle diplaced laterally</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Kocher’s</div><div class=\"answer-line\">Milch</div><div class=\"answer-line\">Hippocratic</div><div class=\"answer-line\">Spaso</div><div class=\"answer-line\">Stimson</div><div class=\"answer-line\">Scapular rotation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">anything reasonable, as long as it includes analgesia and sedation and in safe doses</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 58 year old woman has presented with a painful, swollen left foot.\nThere is no history of trauma nor any previous similar episodes. A photograph of her foot is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give 2 statements describing the clinical image.\n(2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"State the investigation which will be of most benefit in determining the cause of this problem. (1 mark)"},{"id":"c","label":"Part C","prompt":"Complete the table. Give your 2 main differential diagnoses. For each diagnosis, give 2 supportive features you would expect from your investigation in Q2. (6 marks) Differential diagnosis Supportive features 1. 2."}],"propPages":["asset:img80d43776f29a6571ea"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Joint aspirate for M/C/S and cell count</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Differential diagnosis</div><div class=\"answer-line\">Supportive features</div><div class=\"answer-line\">cell count – greater than 50 000</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Septic joint</div><div class=\"answer-line\">Organisms on Gram stain / also accept “no crystals”</div><div class=\"answer-line\">Cell count generally less than 50 000</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>gout</td><td>Negatively bi-refringent crystals</td></tr><tr><td>4.</td><td></td></tr><tr><td>Septic joint</td><td></td></tr><tr><td>-</td><td>Washout in theatre by orthopaedic surgeon</td></tr><tr><td>-</td><td>IV antibioitcs – flucloxacillin 1g QID</td></tr><tr><td>Gout</td><td></td></tr><tr><td>-</td><td>Prednisone 50mg od 3-5 days</td></tr><tr><td>-</td><td>NSAIDs eg ibuprofen 400mg tds</td></tr><tr><td>-</td><td>Colchicine 500mcg QID, max 6mg</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A four week old neonate has been brought to the ED by her mother. The mother states that the baby “won’t stop crying”.","parts":[{"id":"a","label":"Part A","prompt":"In the table below, list 5 differential diagnoses for possible pathology in the child. For each, list one cardinal finding on assessment (history and examination) that would be supportive. (10 marks) Differential diagnosis Assessment finding On assessment, the baby appears well, with no signs of pathology. You are worried about possible post-natal depression in the child’s mother."},{"id":"b","label":"Part B","prompt":"List 8 factors that would put this mother at risk of post-natal depression.\n(8 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ (6)________________________________________________________________________________ (7)________________________________________________________________________________ (8)________________________________________________________________________________ Your assessment is of significant post-natal depression."},{"id":"c","label":"Part C","prompt":"List 4 indications for admission to hospital.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ After you inform her that she needs admission for further treatment, she tells you she wants to leave."},{"id":"d","label":"Part D","prompt":"List 4 components of your verbal de-escalation strategy that you could employ to engage\nher to stay for further management. (4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ Your attempts at verbal de-escalation have been unsuccessful. The mother is now very agitated and attempting to leave."},{"id":"e","label":"Part E","prompt":"List 2 key criteria for the use of involuntary treatment for this patient under your local Mental Health laws. (2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________"},{"id":"f","label":"Part F","prompt":"List 2 drugs you could use for parental sedation, including doses.\n(2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Non-Accidental Injury – signs of trauma – bruising, swelling,</td><td>Sepsis – fever, poor perfusion, focal signs infection</td></tr><tr><td>Occult trauma – corneal abrasions/ skin tourniquet</td><td>Surgical – herniae, abdominal findings – distension, bilious vomiting</td></tr><tr><td>Congenital cardiac – cyanosis, sweating while feeding, heart sounds</td><td>Colic / reflux – observe reflux</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History of depression</div><div class=\"answer-line\">Prior post-partum depression</div><div class=\"answer-line\">History of other mental illness – bipolar</div><div class=\"answer-line\">Recent stressors – pregnancy complications, job issues, health problems</div><div class=\"answer-line\">Baby has health problems or special needs</div><div class=\"answer-line\">Feeding difficulties</div><div class=\"answer-line\">Relationship issues</div><div class=\"answer-line\">Lack of supports</div><div class=\"answer-line\">Unwanted pregnancy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Psychosis</div><div class=\"answer-line\">Admission of thoughts of infanticide/harm</div><div class=\"answer-line\">Thoughts of self-harm</div><div class=\"answer-line\">Any suicidality (any other SADPERSONS type stuff)</div><div class=\"answer-line\">Poor social supports</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Identify reasons for wanting to leave – ie other children, engagements – offer assistance (ie social</div><div class=\"answer-line\">work)</div><div class=\"answer-line\">Offer to find support person (ie partner, friend)</div><div class=\"answer-line\">Ensure she understands the seriousness of the situation including your concerns about her mental</div><div class=\"answer-line\">health and how this may impact her child</div><div class=\"answer-line\">Explain the benefits from staying in hospital (allows longer observation of child, interactions</div><div class=\"answer-line\">(feeding, sleep etc), may allow rest and ‘break-the-cycle’)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">- has a mental health disorder</div><div class=\"answer-line\">- no less restrictive means of management</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Droperidol 10mg</div><div class=\"answer-line\">Midazolam 5-10mg</div><div class=\"answer-line\">Others possible as long as safe</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"You are part of a pre-hospital medical team that has been tasked to the scene of a school sporting carnival where a 12 year old boy has collapsed. The boy is unconsciousness and is not breathing.","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table regarding Advanced Life Support in this situation. (6 marks) CPR ratio of compressions:breaths Energy dose for defibrillation Dose of adrenaline Timing of adrenaline Dose of amiodarone Timing of amiodarone"},{"id":"b","label":"Part B","prompt":"List 8 causes you would look to correct during the cardiac arrest management.\n(8 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________ (6)________________________________________________________________________________ (7)________________________________________________________________________________ (8)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>CPR ratio of compressions:breaths</td><td>15:2</td></tr><tr><td>Energy dose for defibrillation</td><td>4J/kg</td></tr><tr><td>Dose of adrenaline</td><td>10mcg/kg</td></tr><tr><td colspan=\"2\">After 2nd shock then every 2nd cycle</td></tr><tr><td colspan=\"2\">Timing of adrenaline</td></tr><tr><td>Dose of amiodarone</td><td>5mg/kg</td></tr><tr><td colspan=\"2\">After 3rd shock</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Hypovolemia</div><div class=\"answer-line\">Hyper/hypokalaemia</div><div class=\"answer-line\">Hypo/hyperthermia</div><div class=\"answer-line\">Tension pneumothorax</div><div class=\"answer-line\">Tamponade</div><div class=\"answer-line\">Toxins</div><div class=\"answer-line\">Thrombosis (cardiac / pulmonary)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 38 year old man is brought to ED with back pain and fever.","parts":[{"id":"a","label":"Part A","prompt":"List 4 key features in his past medical history that would put this man at increased risk of an epidural abscess. (4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ Assessment reveals spinal tenderness at T12."},{"id":"b","label":"Part B","prompt":"List 3 key components of your examination, including the significance of each. (3 marks)\n(1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List and justify 3 investigations you may utilise in the diagnostic approach to suspected\nepidural abscess. (6 marks) TEST JUSTIFICATION Your assessment has confirmed an epidural abscess. The patient has anaphylaxis to penicillin."},{"id":"d","label":"Part D","prompt":"List your antimicrobial therapy. (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Immunosuppression (diabetes, alcoholism, HIV)</div><div class=\"answer-line\">Overlying infection from pressure sores (ie spinal injury)</div><div class=\"answer-line\">Recent instrumentation/spinal surgery/LP/Spinal anaesthetic</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Assess for spinal cord compression – motor and sensory</div><div class=\"answer-line\">Assess for cauda equine syndrome – above and also perianal tone / sensation</div><div class=\"answer-line\">Signs of focal complicating collections – ie secondary abscess sites splenic/paraspinal abscess</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>TEST</td><td>JUSTIFICATION</td></tr><tr><td>CRP</td><td>More sensitive than WCC early in disease evolution</td></tr><tr><td>Blood Culture</td><td>Identifies causative organism – guides directed therapy</td></tr><tr><td>MRI</td><td>Confirms site and extent, confirms co-existant osteomyelitis,</td></tr><tr><td colspan=\"2\">identifies multi-level disease</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">ok here ie 1.5gm or above</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 45 year old man has presented to the ED with left sided abdominal pain.\nTwo images from his abdominal CT scan are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your diagnosis. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 supportive radiological findings on the CT images.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Complete the table by listing your 2 most relevant other investigations with"},{"id":"d","label":"Part D","prompt":"List 4 criteria that would need to be met for discharge of this patient.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"}],"propPages":["asset:img3dbfa73cfe479faf5b","asset:img1a76bbd3b00f75ee7f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left small VUJ ureteric stone</div><div class=\"answer-line\">Mild hydroureter / hydronephrosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Fat stranding around left kidney</div><div class=\"answer-line\">Enlarged left renal pelvis / ureter</div><div class=\"answer-line\">Small stone at left VUJ / bladder wall</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Urine dipstick or M/C/S</td><td>Exclude urinary infection which would require urgent stent</td></tr><tr><td>Urea / creat</td><td>Exclude significant renal impairment especially in someone with</td></tr><tr><td>chronic renal failure (as a complication)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pain well controlled</div><div class=\"answer-line\">No urinary infection</div><div class=\"answer-line\">Tolerating oral intake</div><div class=\"answer-line\">Follow up arranged</div><div class=\"answer-line\">(probably also renal function acceptable)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 70 year old man has presented to the ED with dizziness.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give your diagnosis, supported by 3 ECG abnormalities. (4 marks) Diagnosis ECG abnormalities (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 possible causes of this problem.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 clinical indications for initiating chemical or electrical pacing in this patient.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 3 agents you could use for chemical pacing.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"}],"propPages":["asset:imgc764bf45ebab8ef463"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Complete heart block</div><div class=\"answer-line\">AV dissociation</div><div class=\"answer-line\">QRS rate approx. 40/min</div><div class=\"answer-line\">QRS duration 120ms (broad) with RBBB pattern [need both for this mark]</div><div class=\"answer-line\">-</div><div class=\"answer-line\">(this will represent left bundle escape focus, or junctional escape with pre-existing RBBB)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ischaemia</div><div class=\"answer-line\">Electrolyte eg hyperkalaemia</div><div class=\"answer-line\">Drugs eg beta blockers</div><div class=\"answer-line\">Degenerative disease conducting system</div><div class=\"answer-line\">Infiltrative disorders eg sarcoidosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypotension</div><div class=\"answer-line\">Impaired mentation</div><div class=\"answer-line\">Chest pain</div><div class=\"answer-line\">(anything else that fits with end organ hypoperfusion)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Isoprenaline</div><div class=\"answer-line\">Adrenaline</div><div class=\"answer-line\">Dopamine</div><div class=\"answer-line\">Dobutmaine</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"An 12 month old girl has been brought to the ED with a seizure. The child has been experiencing fevers and has been lethargic for one day.","parts":[{"id":"a","label":"Part A","prompt":"List 4 criteria for a simple febrile convulsion.\n(4 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ The seizure was self-limiting."},{"id":"b","label":"Part B","prompt":"Complete the following table, with justification for the use of the following investigations. (7 marks) Investigation Justification No investigation Urine bag specimen Urine supra-pubic aspiration or catheter specimen Blood culture Chest x-ray Lumbar puncture Full blood count"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">None of the following</div><div class=\"answer-line\">- focal features at onset or during the seizure</div><div class=\"answer-line\">- Duration of more than 15 minutes</div><div class=\"answer-line\">- Recurrence within the same febrile illness</div><div class=\"answer-line\">- Incomplete recovery within 1 hour.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>No investigation</td><td>- Well child, simple febrile convulsion</td></tr><tr><td>-</td><td>Clear source of fever on investigation that does not require</td></tr><tr><td>investigation eg cellulitis</td><td></td></tr><tr><td>-</td><td>immunised</td></tr><tr><td>Urine bag</td><td>- all girls &lt;2 yrs</td></tr><tr><td>specimen</td><td></td></tr><tr><td>-</td><td>will only exclude UTI, positive specimen requires clean catch</td></tr><tr><td>Urine supra-pubic</td><td>- for those children with positive urine bag specimens or some other Hx</td></tr><tr><td>aspiration or</td><td>to suggest UTI (eg recurrent UTIs</td></tr><tr><td>catheter specimen</td><td></td></tr><tr><td>Blood culture</td><td>- for unwell children with suspicion of bacterial illness to direct Ab</td></tr><tr><td>therapy</td><td></td></tr><tr><td>Chest x-ray</td><td>- only for children with clinical signs of pneumonia</td></tr><tr><td>-</td><td>crackles, tachypnoea, decreased O2 sats</td></tr><tr><td>Lumbar puncture</td><td>- for unwell children with suspicion of meningitis (or unwell with</td></tr><tr><td>previous Ab Rx)</td><td></td></tr><tr><td>-</td><td>meningism</td></tr><tr><td>Full blood count</td><td>- for unwell children</td></tr><tr><td>-</td><td>WBC count has some correlation with likelihood of bacterial illness</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 45 year old man has been brought to the ED after falling off a horse.\nHis pelvic x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the pelvic x-ray.\n(3 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Classify the injury. (1 mark) On completion of your full assessment, no other injuries have been identified.\nHis vital signs are:\n\nGCS\nE3 V4 M6 Pulse 140 /min\n\nBP\n75/40 mmHg O2 saturation 100% 6L O2 via Hudson mask The patient is agitated. You have decided in collaboration with your trauma team, that the patient will require attempted embolization of bleeding pelvic vessels in the interventional radiological theatre."},{"id":"c","label":"Part C","prompt":"List 4 steps in your management of this patient, providing rationale for each. (8 marks)\nManagement step Rationale"}],"propPages":["asset:imge7baa484e14ec0ad4f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Wide symphysis pubis</div><div class=\"answer-line\">Left SI joint completely disrupted</div><div class=\"answer-line\">Fractured left superior and inferior pubic rami</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Grade 3 AP compression fracture</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Management step</td><td>Rationale</td></tr><tr><td>Attempt to close pelvic ring to minimise</td><td></td></tr><tr><td>haemorrhage</td><td></td></tr><tr><td>Apply pelvic binder</td><td></td></tr><tr><td>Very painful injury</td><td></td></tr><tr><td>IV morphine 2.5mg aliquots</td><td>- Analgesia will facilitate ongoing</td></tr><tr><td>management and agitation</td><td></td></tr><tr><td>Intubation / ventilation</td><td>Will allow control of patient to facilitate</td></tr><tr><td>angiography</td><td></td></tr><tr><td>Blood product resuscitation</td><td>Use massive transfusion protocol with ratios</td></tr><tr><td>1:1:1 packed cells:FFP:platelets</td><td></td></tr><tr><td>Allow permissive hypotension to minimise</td><td></td></tr><tr><td>ongoing blood loss</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 4 year old boy has been brought to ED with a petechial rash.\n\nInvestigations have revealed a platelet count of 5 x 109/L. (ref range 150-450 x 109 /L)","parts":[{"id":"a","label":"Part A","prompt":"In the following table, list 3 possible causes of thrombocytopaenia in this child. For each cause, list 2 key historical or examination features that would support this diagnosis, and 2 laboratory findings or investigations that would be useful in confirming the diagnosis. (15 marks) Diagnosis History/Exam findings Laboratory Findings/ Investigations"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>ITP</td><td>Recent viral illness Key is ISOLATED thrombocytopaenia</td></tr><tr><td>Otherwise well child</td><td>60% have detectable anti-platelet</td></tr><tr><td>antibodies (anti-glycoprotein IgG)</td><td></td></tr><tr><td>Normal vitals/perfusion on exam</td><td></td></tr><tr><td>HUS</td><td>Recent gastrointestinal illness (5- Investigations will show HAEMOLYSIS:</td></tr><tr><td>10d before onset of rash (Shiga.</td><td></td></tr><tr><td>-</td><td>Anaemia</td></tr><tr><td>E.Coli) – bloody diarrhoea is</td><td></td></tr><tr><td>hallmark but not required</td><td></td></tr><tr><td>-</td><td>Elevated LDH</td></tr><tr><td>Oligo/anuria or haematuria</td><td></td></tr><tr><td>-</td><td>Decreased Haptoglobin</td></tr><tr><td>Abdominal pain is common</td><td></td></tr><tr><td>-</td><td>Schistocytes on film</td></tr><tr><td>Hypertension</td><td></td></tr><tr><td>-</td><td>Elevated creatinine</td></tr><tr><td>Can have focal neurology</td><td></td></tr><tr><td>DIC</td><td>Rapid onset of severe illness Signs of DIC:</td></tr><tr><td>(meningococcaemia)</td><td></td></tr><tr><td>Febrile</td><td>Prolonged PT</td></tr><tr><td>Signs of distributive shock (ALOC,</td><td>Decreased fibrinogen</td></tr><tr><td>vital sign derangement)</td><td></td></tr><tr><td>Elevated D-Dimer</td><td></td></tr><tr><td>Ecchymoses with poor</td><td></td></tr><tr><td>Other tests for Menigococcaemia:</td><td></td></tr><tr><td>perfusion/mottling</td><td></td></tr><tr><td>Blood Culture</td><td></td></tr><tr><td>PCR testing</td><td></td></tr><tr><td>There may be other acceptable reponses – ie acute leukaemia – this would have corresponding</td><td></td></tr><tr><td>answers of constitutional symptoms – bone pain/fever/lethargy/nightsweats/splenomegaly and lab</td><td></td></tr><tr><td>findings of leucocytosis/anaemia/blasts/elevated LDH but not usually evidence of haemolysis (ie no</td><td></td></tr><tr><td>decrease in haptoglobin/ presence of schistocytes)</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 30 year old male has presented after an intentional slow-release paracetamol overdose.","parts":[{"id":"a","label":"Part A","prompt":"List 2 specific indications for administration of activated charcoal in this patient.\n(2 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ After initial assessment, the patient was commenced on an N-AcetylCysteine infusion whilst awaiting results. The serum paracetamol at 6 hours is shown on the nomogram in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List the criteria for cessation of N-AcetylCysteine therapy in this patient. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 5 criteria for transfer to a liver transplant service in the context of hepatotoxicity from paracetamol. (5 marks) (1)________________________________________________________________________________ (2)________________________________________________________________________________ (3)________________________________________________________________________________ (4)________________________________________________________________________________ (5)________________________________________________________________________________"}],"propPages":["asset:img32c0ff5d587eed7f26"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Non-massive ingestions - &lt;4hrs post ingestion</div><div class=\"answer-line\">Massive (&gt;30gm) – AC indicated up to 24hrs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Repeat paracetamol at another 4 hrs (10hrs) – must be BELOW line and FALLING (indicates non-toxic</div><div class=\"answer-line\">ingestion) 1 mark</div><div class=\"answer-line\">OTHERWISE IF TOXIC INGESTION,</div><div class=\"answer-line\">Has completed NAC therapy AND 1 mark</div><div class=\"answer-line\">ALT &lt;50 and Paracetamol &lt;10 prior to completion 1 mark</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">INR &gt; 3.0 at 48 hours or &gt; 4.5 at any time</td></tr><tr><td>•</td><td>oliguria or creatinine &gt; 200 mmol/L</td></tr><tr><td>•</td><td>persistent acidosis (pH &lt; 7.3) or arterial lactate &gt; 3 mmol/L</td></tr><tr><td>•</td><td>systolic hypotension with BP &lt;80 mmHg, despite resuscitation</td></tr><tr><td>•</td><td>hypoglycaemia</td></tr><tr><td>•</td><td>severe thrombocytopenia</td></tr><tr><td>•</td><td>encephalopathy of any degree, or ALOC (GCS &lt; 15) in the absence of sedatives.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
